import { formatBudget } from "../domain/budget";
import { useAds } from "../hooks/use-ads";

export function AdList() {
  const ads = useAds();
  return (
    <ul>
      {ads.map((ad) => (
        <li key={ad.id}>
          {ad.title}: {formatBudget(ad.budgetCents)}
        </li>
      ))}
    </ul>
  );
}

src/modules/ads/hooks/use-ads.ts:
import { useEffect, useState } from "react";
import { listAds } from "../data/ads";
import type { Ad } from "../types";

export function useAds(): Ad[] {
  const [ads, setAds] = useState<Ad[]>([]);
  useEffect(() => {
    void listAds().then(setAds);
  }, []);
  return ads;
}

src/modules/ads/data/ads.ts:
import { pb } from "@/backend/client";
import type { Ad } from "../types";

export function listAds(): Promise<Ad[]> {
  return pb.collection("ads").getFullList<Ad>();
}

